// Some portions generated by Codex
package org.eclipse.rdf4j.http.server;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.file.Files;
import java.nio.file.Path;

import org.eclipse.rdf4j.rio.helpers.JSONLDSettings;
import org.junit.jupiter.api.Test;

class DockerJsonLdSecureDefaultTest {

	@Test
	void dockerImagesRetainTheSecureJsonLdParserDefault() throws Exception {
		assertThat(JSONLDSettings.SECURE_MODE.getDefaultValue()).isTrue();

		Path docker = findRepositoryRoot().resolve("docker");
		for (String dockerfile : new String[] { "Dockerfile-jetty", "Dockerfile-tomcat" }) {
			assertThat(Files.readString(docker.resolve(dockerfile)))
					.as(dockerfile + " must not disable JSON-LD secure mode")
					.doesNotContain("-D" + JSONLDSettings.SECURE_MODE.getKey() + "=false");
		}
	}

	private static Path findRepositoryRoot() {
		Path current = Path.of(System.getProperty("maven.multiModuleProjectDirectory", "."))
				.toAbsolutePath()
				.normalize();
		while (current != null) {
			if (Files.isRegularFile(current.resolve("docker/Dockerfile-jetty"))
					&& Files.isRegularFile(current.resolve("docker/Dockerfile-tomcat"))) {
				return current;
			}
			current = current.getParent();
		}
		throw new IllegalStateException("Could not locate RDF4J Dockerfiles");
	}
}
